/**
 * The MD2 look's module. Importing `material/styles/md2` loads the document
 * sheet and adopts the shadow sheet into the shadow roots of hosts flagged
 * `data-style="md2"` (see `applyMd2`).
 *
 * The sheet's declarations are generated by the build into
 * `dist/styles/md2.d.ts` from this file; this module has no runtime of its own.
 */

/** The MD2 sheet, as text: the same rules the document file carries. */
export declare const md2Css: string;

/**
 * Adopts the MD2 sheet into one element's shadow root. Idempotent, and a
 * no-op on a host without a shadow root yet; the import already adopts every
 * host flagged `data-style="md2"`, so this is for a host an application
 * creates later.
 */
export declare function applyMd2(host: Element): void;
